cd src; for u in "https://europepmc.org/articles/PMC11065988/pdf/41598_2024_Article_60529.pdf" "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC11065988/pdf/41598_2024_Article_60529.pdf" "https://pmc.ncbi.nlm.nih.gov/articles/PMC11065988/" "https://www.ncbi.nlm.nih.gov/pmc/utils/oa/oa.fcgi?id=PMC11065988" "https://ftp.ncbi.nlm.nih.gov/pub/pmc/oa_package/" "https://cdn.ncbi.nlm.nih.gov/pmc/blobs/"; do curl -sS -L -m 60 -o tmp.bin -w "%{http_code} %{size_download} %{content_type} $u\n" "$u" 2>&1 | tail -1; done